src:
flowchart TD
    A["클라이언트 PaymentPayload의<br/>extensions 키 하나"] --> B{"서버가 이 키를<br/>광고했는가"}
    B -- "예" --> C["dynamicInfoFields를<br/>양쪽에서 제거"]
    C --> D{"info가 일치하는가"}
    D -- "아니오" --> X["거부<br/>extension_echo_mismatch"]
    D -- "예" --> E{"SERVER_OWNED_INFO_FIELDS에<br/>이 키가 있는가"}
    B -- "아니오" --> E
    E -- "예 - builder-code뿐" --> F{"서버가 선언한 값과<br/>같은가"}
    F -- "아니오" --> X
    F -- "예" --> G["통과"]
    E -- "아니오" --> G

flowchart TD
    A["one extensions key on the<br/>client PaymentPayload"] --> B{"did the server<br/>advertise this key"}
    B -- "yes" --> C["strip dynamicInfoFields<br/>from both sides"]
    C --> D{"does info match"}
    D -- "no" --> X["reject<br/>extension_echo_mismatch"]
    D -- "yes" --> E{"is the key in<br/>SERVER_OWNED_INFO_FIELDS"}
    B -- "no" --> E
    E -- "yes - builder-code only" --> F{"does it match what<br/>the server declared"}
    F -- "no" --> X
    F -- "yes" --> G["pass"]
    E -- "no" --> G
